refinement_engine.liquid_types:
{-@
  type NonEmptyExpr = {e: SExpr | len e > 0}
  type ValidAST     = {a: AST | isWellFormed a && containsNoHoles a}
  type QuineProof   = {p: AST | eval p == p}
  type Synthesis    = {s: AST | satisfiesInvariants s && verifiesSMT s}
@-}

{-@ evalo :: partial:NonEmptyExpr
          -> expected:NonEmptyExpr
          -> {v:Synthesis | matchesSpec partial expected v} @-}

{-@ synthesizeAndVerify :: input:NonEmptyExpr
                        -> {v:ValidAST | preservesInvariants input v} @-}
